namespace CCShieldWindows {
static class Data {
 internal static JavaScriptSerializer Json { get { return new JavaScriptSerializer { MaxJsonLength=4194304 }; } }
 internal static string Text(IDictionary<string,object> x,string k) { return x.ContainsKey(k)&&x[k]!=null?Convert.ToString(x[k]):""; }
 internal static bool Flag(IDictionary<string,object> x,string k) { return x.ContainsKey(k)&&x[k] is bool&&(bool)x[k]; }
 internal static Dictionary<string,object> Map(IDictionary<string,object> x,string k) { return x.ContainsKey(k)?x[k] as Dictionary<string,object>??new Dictionary<string,object>():new Dictionary<string,object>(); }
 internal static string Hash(string value) { using(var h=SHA256.Create()) return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-",""); }
 internal static string Mask(string ip) { var parts=ip.Split('.');return parts.Length==4?parts[0]+"."+parts[1]+".*."+parts[3]:"IPv6"; }
}
sealed class Settings {
 public string Endpoint="http://127.0.0.1:9090";
 public string Secret="";
 public string ClaudePath="";
 public string LaunchId="";
 public bool Strict=false;
 public static readonly string DirectoryPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CCTower","Shield");
 static string FilePath {get{return Path.Combine(DirectoryPath,"settings.dpapi");}}
 static readonly byte[] Entropy=Encoding.UTF8.GetBytes("CCShield.Windows.Settings.1");
 public static bool ReadFailed;
 public static Settings Load() { try { var bytes=ProtectedData.Unprotect(File.ReadAllBytes(FilePath),Entropy,DataProtectionScope.CurrentUser);return Data.Json.Deserialize<Settings>(Encoding.UTF8.GetString(bytes))??new Settings(); }catch{ReadFailed=File.Exists(FilePath);return new Settings();} }
 public void Save() { Directory.CreateDirectory(DirectoryPath);var bytes=ProtectedData.Protect(Encoding.UTF8.GetBytes(Data.Json.Serialize(this)),Entropy,DataProtectionScope.CurrentUser);string temp=FilePath+".tmp";File.WriteAllBytes(temp,bytes);if(File.Exists(FilePath))File.Replace(temp,FilePath,null);else File.Move(temp,FilePath); }
 public Settings Copy() {return new Settings{Endpoint=Endpoint,Secret=Secret,ClaudePath=ClaudePath,LaunchId=LaunchId,Strict=Strict};}
 public static Uri ValidateEndpoint(string text) { Uri uri;IPAddress ip;if(!Uri.TryCreate(text,UriKind.Absolute,out uri)||uri.Scheme!="http"||!IPAddress.TryParse(uri.Host.Trim('[',']'),out ip)||!IPAddress.IsLoopback(ip)||uri.AbsolutePath!="/"||uri.Query!=""||uri.Fragment!=""||uri.UserInfo!="")throw new Exception("监测接口只接受 http://127.0.0.1:端口 或 IPv6 回环地址");return uri; }
}
static class Authenticode {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct FileInfo {public uint Size;public IntPtr Path,Handle,Subject;}
 [StructLayout(LayoutKind.Sequential)]struct TrustData {public uint Size;public IntPtr Callback,Sip;public uint Ui,Revocation,Choice;public IntPtr File;public uint State;public IntPtr StateData,Url;public uint Flags,Context;}
 [DllImport("wintrust.dll",ExactSpelling=true,PreserveSig=true)]static extern int WinVerifyTrust(IntPtr window,ref Guid action,ref TrustData data);
 internal static bool Valid(string path){IntPtr text=IntPtr.Zero,file=IntPtr.Zero;try{text=Marshal.StringToCoTaskMemUni(path);var info=new FileInfo{Size=(uint)Marshal.SizeOf(typeof(FileInfo)),Path=text};file=Marshal.AllocHGlobal(Marshal.SizeOf(typeof(FileInfo)));Marshal.StructureToPtr(info,file,false);var data=new TrustData{Size=(uint)Marshal.SizeOf(typeof(TrustData)),Ui=2,Choice=1,File=file,Flags=0x1000};var action=new Guid("00AAC56B-CD44-11d0-8CC2-00C04FC295EE");return WinVerifyTrust(new IntPtr(-1),ref action,ref data)==0;}catch{return false;}finally{if(file!=IntPtr.Zero)Marshal.FreeHGlobal(file);if(text!=IntPtr.Zero)Marshal.FreeCoTaskMem(text);}}
}
static class NativeProcesses {
 [StructLayout(LayoutKind.Sequential)]struct Basic {public IntPtr Reserved1,Peb,Reserved2,Reserved3,Pid,Parent;}
 [DllImport("ntdll.dll")]static extern int NtQueryInformationProcess(IntPtr p,int c,ref Basic b,int size,out int read);
 internal static Process[] Roots(string path,bool allMatching=false) {if(path=="")return new Process[0];var all=new List<Process>();foreach(var p in Process.GetProcessesByName("Claude")){try{if(String.Equals(p.MainModule.FileName,path,StringComparison.OrdinalIgnoreCase))all.Add(p);else p.Dispose();}catch{p.Dispose();}}
 if(allMatching)return all.ToArray();var ids=new HashSet<int>(all.Select(p=>p.Id));var roots=all.Where(p=>{try{Basic b=new Basic();int read;if(NtQueryInformationProcess(p.Handle,0,ref b,Marshal.SizeOf(typeof(Basic)),out read)!=0)return p.MainWindowHandle!=IntPtr.Zero;return !ids.Contains(b.Parent.ToInt32());}catch{return false;}}).ToArray();foreach(var p in all)if(!roots.Contains(p))p.Dispose();return roots; }
 internal static bool Matches(Process p,string path,DateTime born) {try{return !p.HasExited&&p.StartTime.ToUniversalTime()==born&&String.Equals(p.MainModule.FileName,path,StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 internal static int Count(string path){var roots=Roots(path);int count=roots.Length;foreach(var p in roots)p.Dispose();return count;}
 internal static async Task<bool> Stop(string path) {var roots=Roots(path,true);var records=new List<KeyValuePair<Process,DateTime>>();foreach(var p in roots){try{records.Add(new KeyValuePair<Process,DateTime>(p,p.StartTime.ToUniversalTime()));}catch{p.Dispose();}}foreach(var x in records){try{if(Matches(x.Key,path,x.Value))x.Key.CloseMainWindow();}catch{}}
 await Task.Delay(5000);foreach(var x in records){try{if(Matches(x.Key,path,x.Value))x.Key.Kill();}catch{}}await Task.Delay(700);bool ended=records.All(x=>!Matches(x.Key,path,x.Value));foreach(var x in records)x.Key.Dispose();return ended; }
 internal static bool Trusted(string path) {try{if(!String.Equals(Path.GetFileName(path),"Claude.exe",StringComparison.OrdinalIgnoreCase)||!File.Exists(path)||!Authenticode.Valid(path))return false;var cert=new X509Certificate2(X509Certificate.CreateFromSignedFile(path));if(cert.Subject.IndexOf("Anthropic",StringComparison.OrdinalIgnoreCase)<0)return false;using(var chain=new X509Chain()){chain.ChainPolicy.RevocationMode=X509RevocationMode.NoCheck;return chain.Build(cert);}}catch{return false;} }
}
static class Probe {
 static string Request(Uri uri,string secret,int limit,bool head,WebProxy proxy) {var r=(HttpWebRequest)WebRequest.Create(uri);r.Timeout=4500;r.ReadWriteTimeout=4500;r.AllowAutoRedirect=false;r.Method=head?"HEAD":"GET";r.UserAgent="CCShield-Windows/1.0";r.Proxy=proxy;if(secret!="")r.Headers["Authorization"]="Bearer "+secret;
 try{using(var response=(HttpWebResponse)r.GetResponse()){if(head)return "ok";using(var stream=response.GetResponseStream()){var bytes=new List<byte>();byte[] buf=new byte[4096];int n;while((n=stream.Read(buf,0,buf.Length))>0){if(bytes.Count+n>limit)throw new InvalidDataException();bytes.AddRange(buf.Take(n));}return Encoding.UTF8.GetString(bytes.ToArray());}}}
 catch(WebException e){if(head&&e.Response is HttpWebResponse){using(e.Response)return "ok";}throw;}}
 static Dictionary<string,object> Api(Settings c,string path) {var baseUri=Settings.ValidateEndpoint(c.Endpoint);return Data.Json.Deserialize<Dictionary<string,object>>(Request(new Uri(baseUri,path),c.Secret,4194304,false,null));}
 static string Node(Dictionary<string,object> proxies) {var chain=new List<string>();var seen=new HashSet<string>();string name="GLOBAL";for(int i=0;i<32;i++){if(!seen.Add(name))return "";object v;if(!proxies.TryGetValue(name,out v))return "";var p=v as Dictionary<string,object>;if(p==null)return "";string type=Data.Text(p,"type");if(new[]{"Direct","Reject","RejectDrop","Pass","Compatible"}.Contains(type))return "";chain.Add(name+":"+type);string next=Data.Text(p,"now");if(next!=""){chain.Add("selected="+next);name=next;continue;}if(p.ContainsKey("all"))return "";if(!new[]{"Shadowsocks","ShadowsocksR","Trojan","Vmess","Vless","Hysteria","Hysteria2","Tuic","WireGuard","Socks5","Http","Snell","SSH"}.Contains(type))return "";return Data.Hash(String.Join("|",chain));}return "";}
 static string PowerShell(Settings c) {string code;using(var reader=new StreamReader(Assembly.GetExecutingAssembly().GetManifestResourceStream("WindowsShield.Probe.ps1")))code=reader.ReadToEnd();
 var p=new Process();p.StartInfo=new ProcessStartInfo{FileName=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe"),Arguments="-NoProfile -NonInteractive -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(code)),UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8};p.StartInfo.EnvironmentVariables["CLAUDE_SHIELD_TARGET"]=c.ClaudePath;p.Start();var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(12000)){p.Kill();throw new TimeoutException();}if(p.ExitCode!=0)throw new Exception("路由采样失败");return stdout.GetAwaiter().GetResult(); }
 static bool ProxyMatches(int port,int mixed) {using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Internet Settings")){if(key==null||Convert.ToInt32(key.GetValue("ProxyEnable",0))!=1)return false;string raw=Convert.ToString(key.GetValue("ProxyServer",""));string https=raw;if(raw.Contains("=")){https=raw.Split(';').FirstOrDefault(x=>x.StartsWith("https=",StringComparison.OrdinalIgnoreCase));if(https==null)return false;https=https.Substring(6);}Uri uri;IPAddress ip;if(!Uri.TryCreate("http://"+https,UriKind.Absolute,out uri)||!IPAddress.TryParse(uri.Host.Trim('[',']'),out ip)||!IPAddress.IsLoopback(ip))return false;return uri.Port==port&&port>0||uri.Port==mixed&&mixed>0;}}
 static string Trace(string host,WebProxy proxy) {string text=Request(new Uri("https://"+host+"/cdn-cgi/trace"),"",16384,false,proxy);var m=Regex.Match(text,@"(?m)^ip=([^\r\n]+)");IPAddress address;return m.Success&&IPAddress.TryParse(m.Groups[1].Value.Trim(),out address)?address.ToString():"";}
 static string Stun() {foreach(string host in new[]{"stun.l.google.com","stun.cloudflare.com"}){try{using(var udp=new UdpClient(AddressFamily.InterNetwork)){udp.Client.ReceiveTimeout=2200;udp.Client.SendTimeout=2200;var addresses=Dns.GetHostAddresses(host);var address=addresses.First(a=>a.AddressFamily==AddressFamily.InterNetwork);byte[] msg=new byte[20];msg[0]=0;msg[1]=1;msg[4]=0x21;msg[5]=0x12;msg[6]=0xa4;msg[7]=0x42;using(var random=RandomNumberGenerator.Create()){var id=new byte[12];random.GetBytes(id);Buffer.BlockCopy(id,0,msg,8,12);}udp.Connect(address,host.Contains("google")?19302:3478);udp.Send(msg,msg.Length);IPEndPoint from=null;byte[] data=udp.Receive(ref from);if(data.Length<20||data[0]!=1||data[1]!=1||!data.Skip(4).Take(16).SequenceEqual(msg.Skip(4)))continue;int end=Math.Min(data.Length,20+data[2]*256+data[3]);for(int i=20;i+4<=end;){int type=data[i]*256+data[i+1],size=data[i+2]*256+data[i+3];if(i+4+size>end)break;if((type==0x20||type==1)&&size>=8&&data[i+5]==1){byte[] ip=data.Skip(i+8).Take(4).ToArray();if(type==0x20)for(int j=0;j<4;j++)ip[j]^=msg[4+j];return new IPAddress(ip).ToString();}i+=4+((size+3)/4)*4;}}}catch{}}return "";}
 internal static Snapshot Run(Settings c) {TimeZoneInfo.ClearCachedData();var s=new Snapshot();Dictionary<string,object> config=null;try{config=Api(c,"/configs");var all=Data.Map(Api(c,"/proxies"),"proxies");s.Node=Node(all);s.Controller=Data.Text(config,"mode")=="global"&&s.Node!="";var tun=Data.Map(config,"tun");s.Tun=Data.Flag(tun,"enable");int port=0,mixed=0;Int32.TryParse(Data.Text(config,"port"),out port);Int32.TryParse(Data.Text(config,"mixed-port"),out mixed);s.Proxy=ProxyMatches(port,mixed);}catch{s.Error="无法确认本机控制 API，请检查接口与密钥";}
 try{var os=Data.Json.Deserialize<Dictionary<string,object>>(PowerShell(c));s.Tun=s.Tun&&Data.Flag(os,"RouteKnown")&&Data.Flag(os,"TunRoute");s.Route=Data.Text(os,"TunName");s.V6=Data.Flag(os,"V6Safe");s.ConnectionsKnown=Data.Flag(os,"ConnectionsKnown");s.Direct=Data.Flag(os,"Direct");s.DiscoveryPath=Data.Text(os,"ClaudePath");s.DiscoveryLaunch=Data.Text(os,"LaunchId");}catch{s.Tun=false;s.Error="Windows 路由与连接采样未完成";}
 if(s.Controller&&s.Proxy&&s.Tun&&s.V6){try{int port=Convert.ToInt32(config.ContainsKey("mixed-port")?config["mixed-port"]:config["port"]);if(port<=0)port=Convert.ToInt32(config["port"]);var proxy=new WebProxy("http://127.0.0.1:"+port);string ai="",com="";bool api=false,web=false,dns=false,certificate=false;
 var jobs=new[]{Task.Run(()=>{try{ai=Trace("claude.ai",proxy);}catch(WebException e){if(e.Status==WebExceptionStatus.TrustFailure)certificate=true;}catch{}}),Task.Run(()=>{try{com=Trace("claude.com",proxy);}catch(WebException e){if(e.Status==WebExceptionStatus.TrustFailure)certificate=true;}catch{}}),Task.Run(()=>{try{api=Request(new Uri("https://api.anthropic.com/"),"",0,true,proxy)=="ok";}catch(WebException e){if(e.Status==WebExceptionStatus.TrustFailure)certificate=true;}catch{}}),Task.Run(()=>{try{web=Request(new Uri("https://claude.ai/"),"",0,true,proxy)=="ok";}catch(WebException e){if(e.Status==WebExceptionStatus.TrustFailure)certificate=true;}catch{}}),Task.Run(()=>{try{dns=Dns.GetHostAddresses("claude.ai").Length>0;}catch{}}),Task.Run(()=>{s.Udp=Stun();})};Task.WaitAll(jobs);s.Certificate=certificate;s.Conflict=ai!=""&&com!=""&&ai!=com;s.EdgeComplete=!s.Conflict&&ai!=""&&ai==com;s.Exit=!s.Conflict?(ai!=""?ai:com):"";s.Transport=api&&web;s.Dns=dns;
 }catch{s.Error="辅助网络探测未完成";}}
 return s; }
}
