 void Render(){if(rows==null)return;rows.BeginUpdate();rows.Items.Clear();var s=latest;if(s!=null){Add("节点与全局模式",s.Controller,s.Controller?"已确认当前选择链":"未确认，配置本机监测接口");Add("系统代理",s.Proxy,s.Proxy?"指向当前本机代理":"未匹配");Add("IPv4 TUN 路由",s.Tun,s.Tun?s.Route:"未确认受支持的 TUN");Add("IPv6 路径",s.V6,s.V6?"无默认出口或同一 TUN":"未确认");Add("实际 TCP 路由",s.Direct?false:(s.ConnectionsKnown?(bool?)null:false),s.Direct?"观察到非 TUN 路由":s.ConnectionsKnown?"本轮未发现异常，不代表全时段覆盖":"采样未完成");Add("DNS 解析",s.Dns,s.Dns?"解析成功；不证明解析器出口":"未取得");Add("HTTPS 传输",s.Transport,s.Certificate?"证书验证失败":s.Transport?"已到达":"未通过，保持证书校验");Add("Claude 出口",s.Exit!="",s.Exit!=""?Data.Mask(s.Exit):s.Conflict?"两个域名出口不同":"未取得");Add("UDP 出口",s.Udp!=""&&s.Exit!=""&&s.Udp==s.Exit,s.Udp==""?"未取得；不视为已阻断":Data.Mask(s.Udp));Add("会话",policy.Admission!="",policy.Admission!=""?"已绑定节点、路由、时区与出口":"待检查准入");}
 rows.EndUpdate();detail.Text=status+(probing?"\n正在巡检…":"");tray.Text=config.Strict?"CC Shield · 戒严":"CC Shield · 瞭望";watch.BackColor=!config.Strict?Color.LightGoldenrodYellow:SystemColors.Control;strict.BackColor=config.Strict?Color.MistyRose:SystemColors.Control;start.Enabled=config.Strict&&!probing&&!starting&&!stopping;stop.Enabled=!stopping&&(policy.Admission!=""||NativeProcesses.Count(config.ClaudePath)>0);settings.Enabled=!starting&&!stopping&&policy.Admission=="";check.Enabled=!probing&&!starting&&!stopping;}
 async void StartProbe(){if(probing||starting||stopping)return;probing=true;int token=generation;Settings copy=config.Copy();Render();Snapshot result;try{result=await Task.Run(()=>Probe.Run(copy));}catch{result=new Snapshot{Error="巡检异常，无法确认环境"};}probing=false;lastProbe=DateTime.UtcNow;if(token!=generation){Render();return;}latest=result;
 if(config.ClaudePath==""&&result.DiscoveryPath!=""&&NativeProcesses.Trusted(result.DiscoveryPath)){config.ClaudePath=result.DiscoveryPath;config.LaunchId=result.DiscoveryLaunch;try{config.Save();}catch{Notify("客户端位置未能保存，请检查用户目录权限");}}
 if(config.Strict&&NativeProcesses.Count(config.ClaudePath)>0){var decision=policy.Evaluate(result,DateTime.UtcNow);status=decision.Note;if(decision.Stop)await EndSession(decision.Note);}
 else {string issue=result.Issue();if(!config.Strict&&NativeProcesses.Count(config.ClaudePath)>0&&issue!=""&&(issue!=lastNotice||DateTime.UtcNow-noticeAt>TimeSpan.FromMinutes(5))){lastNotice=issue;noticeAt=DateTime.UtcNow;Notify(issue+"；瞭望仅提醒");}status=result.Issue()==""?"环境检查通过，可启动 Claude":result.Error!=""?result.Error:result.Issue();}Render();}
 async Task StartChecked(){if(starting||stopping||probing||!config.Strict)return;if(!NativeProcesses.Trusted(config.ClaudePath)){Notify("请先选择有效签名的 Claude 桌面客户端");return;}if(NativeProcesses.Count(config.ClaudePath)>0){Notify("请先正常退出 Claude 再检查启动");return;}
 starting=true;policy.Reset();int token=generation;Settings copy=config.Copy();status="正在执行完整使用前检查…";Render();try{Snapshot s=await Task.Run(()=>Probe.Run(copy));latest=s;if(token!=generation||!config.Strict)return;if(s.Issue()!=""||DateTime.UtcNow-s.At>TimeSpan.FromSeconds(45)){Notify(s.Issue()!=""?s.Issue():"检查过期，请重试");return;}if(NativeProcesses.Count(config.ClaudePath)>0){Notify("检查期间 Claude 已启动，请先退出后重试");return;}
 policy.Admission=s.Binding();policy.Issued=DateTime.UtcNow;launchDeadline=DateTime.UtcNow.AddSeconds(20);
 if(config.LaunchId!=""&&Regex.IsMatch(config.LaunchId,@"^[A-Za-z0-9._!\-]+$"))Process.Start(new ProcessStartInfo("explorer.exe","shell:AppsFolder\\"+config.LaunchId){UseShellExecute=true});
 else Process.Start(new ProcessStartInfo(config.ClaudePath){UseShellExecute=true,WorkingDirectory=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile)});
 status="检查通过，已请求启动；使用中保持节点与网络配置不变";Log("admission","会话已准入");lastProbe=DateTime.MinValue;
 }catch{policy.Reset();Notify("启动未完成，请检查客户端安装");}finally{starting=false;Render();}}
 async Task<bool> EndSession(string reason){if(stopping)return false;stopping=true;generation++;policy.Reset();status="正在结束本次使用…";Render();bool ended=false;try{ended=await NativeProcesses.Stop(config.ClaudePath);}catch{ended=false;}stopping=false;lastStop=DateTime.UtcNow;launchDeadline=DateTime.MinValue;status=reason+(ended?"；本次使用已结束":"；Claude 未能退出，继续值守");Log("stop",status);if(!ended)tray.ShowBalloonTip(5000,"Claude 未能退出","请保存工作并退出 Claude；哨兵继续值守",ToolTipIcon.Warning);Render();return ended;}
 async void Tick(){if(starting||stopping)return;bool running=NativeProcesses.Count(config.ClaudePath)>0;if(config.Strict&&running&&policy.Admission!=""&&(latest==null||DateTime.UtcNow-latest.At>TimeSpan.FromSeconds(45))){await EndSession("关键证据超时，无法继续确认接管");return;}
 if(config.Strict&&running&&policy.Admission==""&&DateTime.UtcNow-lastStop>TimeSpan.FromSeconds(5)){await EndSession("本次启动未获准入");return;}
 if(!running&&policy.Admission!=""&&DateTime.UtcNow>launchDeadline){policy.Reset();status="会话已结束，下次请重新检查";Render();}
 if(DateTime.UtcNow-lastProbe>TimeSpan.FromSeconds(running?10:30))StartProbe(); }
}
static class Tests {
 internal static string Run(){int count=PolicyTests.Run();var original=new byte[]{1,2,3,4};var cipher=ProtectedData.Protect(original,null,DataProtectionScope.CurrentUser);if(!original.SequenceEqual(ProtectedData.Unprotect(cipher,null,DataProtectionScope.CurrentUser)))throw new Exception("DPAPI roundtrip");count++;
 foreach(string uri in new[]{"http://example.com:9090","http://127.0.0.1:9090/a","http://user:pass@127.0.0.1:9090","https://127.0.0.1:9090"}){bool denied=false;try{Settings.ValidateEndpoint(uri);}catch{denied=true;}if(!denied)throw new Exception("endpoint not denied");count++;}
 Settings.ValidateEndpoint("http://127.0.0.1:9090");Settings.ValidateEndpoint("http://[::1]:9090");count+=2;if(Authenticode.Valid(Application.ExecutablePath)||NativeProcesses.Trusted(Application.ExecutablePath))throw new Exception("unsigned executable trusted");count++;return Data.Json.Serialize(new{ok=true,checks=count});}
}
static class Program {
 [STAThread]static void Main(string[] args){ServicePointManager.SecurityProtocol=(SecurityProtocolType)0;
 if(args.Length==1&&args[0]=="--install"){Installer.Install();return;}
 if(args.Length==2&&args[0]=="--self-test"){try{File.WriteAllText(args[1],Tests.Run(),Encoding.UTF8);}catch(Exception e){File.WriteAllText(args[1],Data.Json.Serialize(new{ok=false,error=e.Message}),Encoding.UTF8);Environment.ExitCode=1;}return;}
 if(args.Length==2&&args[0]=="--probe-report"){var s=Probe.Run(Settings.Load());File.WriteAllText(args[1],Data.Json.Serialize(new{controller=s.Controller,proxy=s.Proxy,tun=s.Tun,v6=s.V6,direct=s.Direct,connectionsKnown=s.ConnectionsKnown,transport=s.Transport,dns=s.Dns,edgeKnown=s.Exit!="",udpKnown=s.Udp!="",issue=s.Issue()}),Encoding.UTF8);return;}
 if(args.Length!=0&&!(args.Length==1&&args[0]=="--background")){Environment.ExitCode=2;return;}
 bool created;using(var mutex=new Mutex(true,"Local\\CCShieldWindows-"+Environment.UserName,out created)){if(!created)return;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new MainForm(args.Contains("--background")));}
 }
